import React from 'react';
import Project from './Project';
import data from './../data/projectsData.js';

function Projects() {
  return (
    <section id='projects' className='py-20 px-6 sm:px-8 lg:px-12 relative overflow-hidden'>
      {/* Background Effects */}
      <div className="absolute inset-0 opacity-20">
        <div className="absolute top-0 right-0 w-72 h-72 bg-gradient-to-l from-purple-500/30 to-transparent rounded-full blur-3xl"></div>
        <div className="absolute bottom-0 left-0 w-96 h-96 bg-gradient-to-r from-blue-500/20 to-transparent rounded-full blur-3xl"></div>
      </div>

      <div className="max-w-7xl mx-auto relative z-10">
        {/* Enhanced Section Header */}
        <div className="text-center mb-16 animate-fade-in-up">
          <h2 className="text-4xl sm:text-5xl md:text-6xl font-bold text-white mb-6">
            My <span className="text-gradient animate-glow">Projects</span>
          </h2>
          <div className="w-24 h-1 bg-gradient-to-r from-[#6699CC] to-[#58A6FF] mx-auto rounded-full mb-8 shadow-elegant"></div>
          <p className="text-gray-300 text-xl max-w-3xl mx-auto leading-relaxed">
            A showcase of my recent work, featuring modern technologies and innovative solutions
          </p>
        </div>

        {/* Enhanced Projects Grid */}
        <div className="grid-modern animate-fade-in-up" style={{ animationDelay: '0.2s' }}>
          {data.ProjectsData.map((project) => (
            <Project 
              key={project.id} 
              image={project.img}
              name={project.name}
              live={project.liveUrl}
              source={project.sourceUrl}
              desc={project.desc}
              stack={project.stack}
            />
          ))}
        </div>


      </div>
    </section>
  );
}

export default Projects;
